     (swap, $e:expr, ($operand:expr), $prev:pat, $next:pat, $ret:pat, $g:ident, $b:block) => {
         $crate::vstd::atomic_ghost::atomic_with_ghost_update_with_1_operand!(
             swap, $e, $operand, $prev, $next, $ret, $g, $b
